#!/usr/bin/perl

use strict;
use warnings;

use FindBin qw($RealBin);

use lib "$RealBin/../libexec/zram-writeback", '/usr/local/libexec/zram-writeback';

use Zram::Setup::CLI;

exit Zram::Setup::CLI->new()->run(@ARGV);

package Zram::Setup::Mapper;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::Types::Mooselike qw(Str);

use IPC::Open3 qw(open3);
use Symbol qw(gensym);
use Time::HiRes qw(sleep);
use Zram::Config qw(cfg);
use Zram::Error qw(fatal);
use Zram::Path qw(same_path);

has mapper_name => (is => 'ro', isa => Str, default => sub { cfg('ZRAM_BACKING_MAPPER_NAME') });
has mapper_path => (is => 'ro', isa => Str, default => sub { cfg('ZRAM_BACKING_DEVICE') });
has raw_path    => (is => 'ro', isa => Str, default => sub { cfg('ZRAM_BACKING_RAW_DEVICE') });

sub _capture {
    my ($self, @command) = @_;
    my $stderr = gensym;
    my $pid = open3(undef, my $stdout, $stderr, @command);
    my $out = do { local $/; <$stdout> // '' };
    my $err = do { local $/; <$stderr> // '' };
    waitpid $pid, 0;
    return ($? >> 8, $out, $err);
}

sub _run {
    my ($self, @command) = @_;
    system @command;
    return $? == 0;
}

sub _wait_for_mapper {
    my ($self, $seconds) = @_;
    for (1 .. $seconds) {
        return 1 if -b $self->mapper_path();
        sleep 1;
    }
    return -b $self->mapper_path() ? 1 : 0;
}

sub _mapped_source {
    my ($self) = @_;
    my ($status, $out) = $self->_capture('/usr/sbin/cryptsetup', 'status', $self->mapper_name());
    return undef if $status != 0;
    my ($source) = $out =~ /^\s*device:\s*(\S+)\s*$/m;
    return $source;
}

sub ensure_open {
    my ($self) = @_;
    -b $self->raw_path() or fatal('missing raw zram writeback partition ' . $self->raw_path());
    if (-b $self->mapper_path()) {
        my $source = $self->_mapped_source();
        defined $source && same_path($source, $self->raw_path())
            or fatal('existing zram writeback mapper does not match its configured raw backing device');
        return 1;
    }

    for my $module (qw(dm_mod dm_crypt)) {
        $self->_run('/usr/sbin/modprobe', $module);
    }
    my $key_bytes = cfg('DMCRYPT_EPHEMERAL_KEY_SIZE') / 8;
    $self->_run(
        '/usr/sbin/cryptsetup',
        'open',
        '--type', 'plain',
        '--batch-mode',
        '--key-file', cfg('DMCRYPT_RANDOM_KEY_FILE'),
        '--keyfile-size', $key_bytes,
        '--cipher', cfg('DMCRYPT_EPHEMERAL_CIPHER'),
        '--key-size', cfg('DMCRYPT_EPHEMERAL_KEY_SIZE'),
        '--hash', cfg('DMCRYPT_EPHEMERAL_HASH'),
        $self->raw_path(),
        $self->mapper_name(),
    ) or fatal('failed to open ephemeral zram writeback mapper ' . $self->mapper_name());
    $self->_wait_for_mapper(10)
        or fatal('zram writeback mapper did not appear: ' . $self->mapper_path());
    return 1;
}

sub close {
    my ($self) = @_;
    return 1 if !-b $self->mapper_path();
    my $source = $self->_mapped_source();
    defined $source && same_path($source, $self->raw_path())
        or fatal('zram writeback mapper does not match its configured raw backing device');
    $self->_run('/usr/sbin/cryptsetup', 'close', $self->mapper_name())
        or fatal('failed to close ephemeral zram writeback mapper ' . $self->mapper_name());
    return 1;
}

1;

package Zram::Setup::Config;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::Types::Mooselike qw(Bool Str);

use Zram::Config qw(load_config validate_config cfg);
use Zram::Error qw(fatal);

has defaults_path => (
    is      => 'ro',
    isa     => Str,
    default => sub { $ENV{ZRAM_DEFAULT_PATH} // '/etc/default/zram-writeback' },
);

has policy_path => (
    is      => 'ro',
    isa     => Str,
    default => sub { $ENV{ZRAM_POLICY_CONFIG} // '/etc/zram-writeback.conf' },
);

has enabled => (
    is      => 'rw',
    isa     => Bool,
    default => sub { 1 },
);

sub _read_defaults {
    my ($self) = @_;
    my $path = $self->defaults_path();

    $path =~ m{\A/(?:[A-Za-z0-9_.:+-]+/)*[A-Za-z0-9_.:+-]+\z}
        or fatal("zram defaults path must be a safe absolute path: $path");
    -r $path or fatal("missing zram defaults $path");
    -l $path and fatal("zram defaults path must not be a symlink: $path");

    open my $fh, '<', $path or fatal("failed to read zram defaults $path: $!");
    my %values;
    my $line_no = 0;
    while (my $line = <$fh>) {
        $line_no++;
        length($line) <= 512 or fatal("oversized zram defaults line $line_no in $path");
        chomp $line;
        $line =~ s/\r\z//;
        next if $line =~ /\A\s*(?:#|\z)/;
        my ($key, $value) = $line =~ /\A([A-Z][A-Z0-9_]*)=(.*)\z/
            or fatal("invalid zram defaults line $line_no in $path");
        $value =~ /\A"(.*)"\z/ and $value = $1;
        $value !~ /["'\x00-\x1f\x7f]/
            or fatal("unsupported quoting or control character in zram defaults $key");
        $value =~ /\A[A-Za-z0-9_./:+= -]*\z/
            or fatal("unsafe value in zram defaults $key");
        $values{$key} = $value;
    }
    close $fh or fatal("failed to close zram defaults $path: $!");

    if (exists $values{ZRAM_ENABLE}) {
        $values{ZRAM_ENABLE} =~ /\A[01]\z/
            or fatal("ZRAM_ENABLE must be 0 or 1, got '$values{ZRAM_ENABLE}'");
        $self->enabled($values{ZRAM_ENABLE} eq '1' ? 1 : 0);
    }
    return \%values;
}

sub load {
    my ($self) = @_;
    $self->_read_defaults();
    load_config($self->policy_path());
    validate_config(require_sysfs => 0);
    return $self;
}

sub cfg {
    my ($self, $key) = @_;
    return cfg($key);
}

1;

package Zram::Setup::Device;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;

use File::Basename qw(basename);
use Time::HiRes qw(sleep);
use Zram::Config qw(cfg);
use Zram::Error qw(fatal);
use Zram::Path qw(same_path);
use Zram::Setup::BackingDevice;
use Zram::Setup::Sysfs;
use Zram::Sizing qw(bytes_to_writeback_pages);
use Zram::Swap qw(swap_active);
use Zram::Sysfs qw(normalize_attr);
use Zram::Tuning qw(writeback_batch_size_for_state);

has sysfs => (is => 'ro', default => sub { Zram::Setup::Sysfs->new() });
has backing => (is => 'ro', default => sub { Zram::Setup::BackingDevice->new() });

sub _run {
    my ($self, @command) = @_;
    system @command;
    return $? == 0;
}

sub _wait_for_block {
    my ($self, $device, $timeout) = @_;
    for (1 .. $timeout) {
        return 1 if -b $device;
        sleep 1;
    }
    return -b $device ? 1 : 0;
}

sub _is_uninitialized {
    my ($self) = @_;
    my $state = $self->sysfs()->read('initstate');
    my $size = $self->sysfs()->read_uint('disksize') // 0;
    return $size == 0 && (!defined $state || $state eq '' || $state eq '0') ? 1 : 0;
}

sub _wait_uninitialized {
    my ($self, $timeout) = @_;
    for (1 .. $timeout) {
        return 1 if $self->_is_uninitialized();
        sleep 1;
    }
    return $self->_is_uninitialized();
}

sub _wait_swap_inactive {
    my ($self, $timeout) = @_;
    for (1 .. $timeout) {
        return 1 if !swap_active(cfg('ZRAM_SWAP_DEVICE'));
        sleep 1;
    }
    return !swap_active(cfg('ZRAM_SWAP_DEVICE'));
}

sub _clear_runtime_state {
    my ($self) = @_;
    my $runtime = cfg('ZRAM_RUNTIME_DIR');
    my $name = cfg('ZRAM_SWAP_DEVICE_NAME');
    for my $path ("$runtime/writeback-budget.state", "$runtime/$name.metrics") {
        next if !-e $path && !-l $path;
        -d $path and fatal("unexpected directory in zram runtime state path: $path");
        unlink $path or fatal("failed to clear stale zram runtime state $path: $!");
    }
}

sub reset {
    my ($self) = @_;
    my $device = cfg('ZRAM_SWAP_DEVICE');
    -d cfg('ZRAM_SYSFS') or fatal('zram sysfs path is unavailable: ' . cfg('ZRAM_SYSFS'));
    if (swap_active($device)) {
        $self->_run('/usr/sbin/swapoff', $device) or fatal("failed to swapoff $device");
        $self->_wait_swap_inactive(10) or fatal("zram swap stayed active after swapoff: $device");
    }
    if ($self->_is_uninitialized()) {
        $self->_clear_runtime_state();
        return 1;
    }
    if ($self->_run('/usr/sbin/zramctl', '--reset', $device) && $self->_wait_uninitialized(5)) {
        $self->_clear_runtime_state();
        return 1;
    }
    $self->sysfs()->required('reset', 1, 'zram reset');
    $self->_wait_uninitialized(5) or fatal("zram reset did not reach uninitialized state for $device");
    $self->_clear_runtime_state();
    return 1;
}

sub _memory_mib {
    my ($self) = @_;
    open my $fh, '<', cfg('ZRAM_PROCFS_ROOT') . '/meminfo'
        or fatal('unable to determine total RAM');
    while (my $line = <$fh>) {
        if ($line =~ /\AMemTotal:\s+([0-9]+)\s+kB\z/) {
            close $fh;
            return int(($1 + 1023) / 1024);
        }
    }
    close $fh;
    fatal('unable to determine total RAM');
}

sub _backing_mib {
    my ($self) = @_;
    my $device = cfg('ZRAM_BACKING_DEVICE');
    -b $device or fatal("missing block device for size probe: $device");
    open my $fh, '-|', '/usr/sbin/blockdev', '--getsize64', $device
        or fatal("unable to determine block device size for $device");
    my $bytes = <$fh>;
    close $fh;
    defined $bytes && $bytes =~ /\A([0-9]+)\s*\z/ && $1 > 0
        or fatal("unable to determine block device size for $device");
    return int(($1 + 1_048_575) / 1_048_576);
}

sub _dynamic_sizes {
    my ($self) = @_;
    my $ram = $self->_memory_mib();
    my $size = int(($ram * cfg('ZRAM_SIZE_PERCENT') + 99) / 100);
    $size = cfg('ZRAM_SIZE_MIN_MIB') if $size < cfg('ZRAM_SIZE_MIN_MIB');
    $size = cfg('ZRAM_SIZE_MAX_MIB') if $size > cfg('ZRAM_SIZE_MAX_MIB');
    my $mem_limit = int(($size * cfg('ZRAM_MEM_LIMIT_PERCENT') + 99) / 100);
    $mem_limit = $size if $mem_limit > $size;

    my $writeback_pages = 0;
    if (cfg('ZRAM_WRITEBACK_ENABLED') && cfg('ZRAM_WRITEBACK_LIMIT_ENABLE')) {
        my $backing = $self->_backing_mib();
        my $reserve = 128;
        $backing > $reserve or fatal("zram backing device is too small after reserve: ${backing} MiB");
        my $usable = $backing - $reserve;
        my $limit = int(($size * cfg('ZRAM_WRITEBACK_LIMIT_PCT') + 99) / 100);
        my $cap = int($usable / 2);
        $cap = $usable if $cap < 1024;
        $limit = $cap if $limit > $cap;
        $writeback_pages = bytes_to_writeback_pages('zram writeback limit', $limit * 1_048_576);
    }
    return ($size, $mem_limit, $writeback_pages);
}

sub _configure_algorithms {
    my ($self) = @_;
    my $available = $self->sysfs()->read('comp_algorithm') // '';
    my $primary = cfg('ZRAM_COMPRESSION_ALGORITHM');
    $available =~ /(?:\A|\s|\[)\Q$primary\E(?:\]|\s|\z)/
        or fatal("primary zram algorithm $primary is unavailable");
    $self->sysfs()->required('comp_algorithm', $primary, 'zram comp_algorithm');
    for my $tier (1 .. 3) {
        next if !cfg("ZRAM_TIER${tier}_ENABLE");
        my $algorithm = cfg("ZRAM_TIER${tier}_ALGORITHM");
        my $priority = cfg("ZRAM_TIER${tier}_PRIORITY");
        $self->sysfs()->required(
            'recomp_algorithm',
            "algo=$algorithm priority=$priority",
            "zram recompression tier $tier algorithm",
        );
        my $level = cfg("ZRAM_TIER${tier}_LEVEL");
        next if !$level;
        $self->sysfs()->required(
            'algorithm_params',
            "algo=$algorithm priority=$priority level=$level",
            "zram recompression tier $tier parameters",
        );
    }
    my $params = cfg('ZRAM_ALGORITHM_PARAMS');
    $self->sysfs()->required('algorithm_params', $params, 'zram algorithm_params')
        if defined $params && $params ne '';
}

sub _configure_writeback {
    my ($self, $writeback_pages) = @_;
    return if !cfg('ZRAM_WRITEBACK_ENABLED');
    $self->sysfs()->required('backing_dev', cfg('ZRAM_BACKING_DEVICE'), 'zram backing_dev');
    if (cfg('ZRAM_COMPRESSED_WRITEBACK')) {
        $self->sysfs()->candidates('compressed_writeback', 'zram compressed_writeback', qw(yes 1))
            or fatal('failed to set zram compressed_writeback');
    }
    $self->sysfs()->required(
        'writeback_batch_size',
        writeback_batch_size_for_state('normal'),
        'zram initial writeback_batch_size',
    );
    $self->sysfs()->required(
        'writeback_limit_enable',
        cfg('ZRAM_WRITEBACK_LIMIT_ENABLE'),
        'zram writeback_limit_enable',
    );
    $self->sysfs()->required('writeback_limit', $writeback_pages, 'zram writeback_limit')
        if cfg('ZRAM_WRITEBACK_LIMIT_ENABLE');
}

sub start {
    my ($self) = @_;
    my $device = cfg('ZRAM_SWAP_DEVICE');
    if (!-b $device) {
        $self->_run('/usr/sbin/modprobe', 'zram', 'num_devices=1')
            or fatal('failed to load zram kernel module');
    }
    $self->_wait_for_block($device, 10) or fatal("zram device node not present: $device");
    -d cfg('ZRAM_SYSFS') or fatal('zram sysfs path is unavailable: ' . cfg('ZRAM_SYSFS'));
    $self->backing()->prepare() if cfg('ZRAM_WRITEBACK_ENABLED');
    $self->reset();
    my ($size_mib, $mem_mib, $writeback_pages) = $self->_dynamic_sizes();
    my $streams = cfg('ZRAM_MAX_COMP_STREAMS');
    $streams = 1 if !$streams;
    $self->sysfs()->optional('max_comp_streams', $streams, 'zram max_comp_streams');
    $self->_configure_algorithms();
    $self->_configure_writeback($writeback_pages);
    $self->sysfs()->required('mem_limit', $mem_mib * 1_048_576, 'zram mem_limit');
    $self->sysfs()->required('disksize', $size_mib * 1_048_576, 'zram disksize');
    $self->sysfs()->optional('mem_used_max', 0, 'zram mem_used_max reset');
    $self->_run('/sbin/mkswap', '-L', 'zram0', $device) or fatal("failed to format zram swap $device");
    $self->_run('/sbin/swapon', '-p', cfg('ZRAM_SWAP_PRIORITY'), $device)
        or fatal("failed to activate zram swap $device");
    return 0;
}

sub stop {
    my ($self) = @_;
    $self->reset();
    $self->backing()->close() if cfg('ZRAM_WRITEBACK_ENABLED');
    return 0;
}

sub wait_backing {
    my ($self) = @_;
    return 0 if !cfg('ZRAM_WRITEBACK_ENABLED');
    $self->backing()->wait_until_ready();
    return 0;
}

sub status {
    my ($self) = @_;
    my $device = cfg('ZRAM_SWAP_DEVICE');
    my $backing = cfg('ZRAM_BACKING_DEVICE');
    my $state = $self->sysfs()->read('initstate') // 'unknown';
    my $ro = -b $backing ? $self->backing()->_block_read_only($backing) : undef;
    printf "enabled=1\n";
    printf "zram_device=%s\n", $device;
    printf "zram_device_present=%d\n", -b $device ? 1 : 0;
    printf "zram_sysfs=%s\n", cfg('ZRAM_SYSFS');
    printf "zram_sysfs_exists=%d\n", -d cfg('ZRAM_SYSFS') ? 1 : 0;
    printf "zram_initialized=%d\n", $self->_is_uninitialized() ? 0 : 1;
    printf "zram_swap_active=%d\n", swap_active($device) ? 1 : 0;
    printf "backing_mapper=%s\n", cfg('ZRAM_BACKING_MAPPER_NAME');
    printf "backing_device=%s\n", $backing;
    printf "backing_mapper_exists=%d\n", -b $backing ? 1 : 0;
    printf "backing_mapper_writable=%d\n", defined $ro && !$ro ? 1 : 0;
    return 0;
}

1;

package Zram::Setup::Sysfs;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::Types::Mooselike qw(Str);

use Zram::Config qw(cfg);
use Zram::Error qw(fatal);
use Zram::Sysfs qw(normalize_attr read_uint_attr write_attr_optional write_attr_required);

has root => (
    is      => 'ro',
    isa     => Str,
    default => sub { cfg('ZRAM_SYSFS') },
);

sub path {
    my ($self, $name) = @_;
    defined $name && $name =~ /\A[A-Za-z0-9_.-]+\z/
        or fatal('unsafe zram sysfs attribute name');
    return $self->root() . "/$name";
}

sub read {
    my ($self, $name) = @_;
    return normalize_attr($self->path($name));
}

sub read_uint {
    my ($self, $name) = @_;
    return read_uint_attr($self->path($name));
}

sub required {
    my ($self, $name, $value, $description) = @_;
    return write_attr_required($self->path($name), $value, $description);
}

sub optional {
    my ($self, $name, $value, $description) = @_;
    return write_attr_optional($self->path($name), $value, $description);
}

sub candidates {
    my ($self, $name, $description, @values) = @_;
    return Zram::Sysfs::try_values($self->path($name), $description, @values);
}

1;

