package Zram::Setup::Lifecycle;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::Types::Mooselike qw(Object);

use Zram::Setup::Device;
use Zram::Setup::Lock;

has config => (is => 'ro', isa => Object, required => 1);
has device => (is => 'ro', default => sub { Zram::Setup::Device->new() });
has lock   => (is => 'ro', default => sub { Zram::Setup::Lock->new() });

sub run {
    my ($self, $action) = @_;
    if ($action eq 'status') {
        return 0 if !$self->config()->enabled() && do { print "enabled=0\n"; 1 };
        return $self->device()->status();
    }
    return 0 if !$self->config()->enabled();

    my $guard = $self->lock()->acquire();
    return $self->device()->start()        if $action eq 'start';
    return $self->device()->stop()         if $action eq 'stop';
    return $self->device()->reset()        if $action eq 'reset';
    return $self->device()->wait_backing() if $action eq 'wait-backing';
    die "unreachable zram lifecycle action\n";
}

1;

package Zram::Setup::CLI;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;

use Zram::Error qw(usage_error);
use Zram::Setup::Config;
use Zram::Setup::Lifecycle;

sub run {
    my ($self, @argv) = @_;
    @argv == 1 or usage_error('usage: zram-device-setup {start|stop|reset|wait-backing|status}');

    my $action = $argv[0];
    $action =~ /\A(?:start|stop|reset|wait-backing|status)\z/
        or usage_error('usage: zram-device-setup {start|stop|reset|wait-backing|status}');

    my $config = Zram::Setup::Config->new()->load();
    return Zram::Setup::Lifecycle->new(config => $config)->run($action);
}

1;

package Zram::Setup::BackingDevice;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;

use File::Basename qw(basename);
use Zram::Config qw(cfg);
use Zram::Error qw(fatal);
use Zram::Path qw(same_path);
use Zram::Setup::Mapper;
use Zram::Swap qw(swap_active);
use Zram::Sysfs qw(read_first_line);

has mapper => (
    is      => 'ro',
    default => sub { Zram::Setup::Mapper->new() },
);

sub _block_read_only {
    my ($self, $device) = @_;
    my $name = basename($device);
    $name =~ /\A[A-Za-z0-9_.:+-]+\z/ or fatal("unsafe backing device name: $device");
    my $value = read_first_line(cfg('ZRAM_SYSFS_ROOT') . "/class/block/$name/ro");
    return undef if !defined $value || $value !~ /\A[01]\z/;
    return int $value;
}

sub _mounted {
    my ($self, $device) = @_;
    open my $fh, '<', cfg('ZRAM_PROCFS_ROOT') . '/mounts'
        or fatal('failed to read mount state');
    while (my $line = <$fh>) {
        my ($source) = split /\s+/, $line, 2;
        if (defined $source && same_path($source, $device)) {
            close $fh;
            return 1;
        }
    }
    close $fh;
    return 0;
}

sub prepare {
    my ($self) = @_;
    $self->mapper()->ensure_open();
    my $device = cfg('ZRAM_BACKING_DEVICE');
    -b $device or fatal("missing zram backing device $device");
    !same_path($device, cfg('ZRAM_SWAP_DEVICE'))
        or fatal('zram swap device and backing device must differ');
    my $read_only = $self->_block_read_only($device);
    defined $read_only && !$read_only or fatal("zram backing device is read-only: $device");
    !$self->_mounted($device) or fatal("zram backing device must not be mounted: $device");
    !swap_active($device) or fatal("zram backing device must not be active swap: $device");

    if (system('/usr/sbin/blkid', $device) == 0) {
        system('/usr/sbin/wipefs', '-a', '-f', $device) == 0
            or fatal("failed to clear stale signatures from $device");
    }
    return 1;
}

sub wait_until_ready {
    my ($self) = @_;
    $self->mapper()->ensure_open();
    my $device = cfg('ZRAM_BACKING_DEVICE');
    -b $device or fatal("missing zram backing device $device");
    my $read_only = $self->_block_read_only($device);
    defined $read_only && !$read_only or fatal("zram backing device is read-only: $device");
    return 1;
}

sub close {
    my ($self) = @_;
    return $self->mapper()->close();
}

1;

