+    my ($self, $path, $wanted) = @_;
+    my $listing = $self->_capture('/usr/bin/dpkg-deb', '-c', $path);
+    return 0 if !defined $listing;
+    return grep { /\Q.$wanted\E\z/ } split /\n/, $listing;
+}
