+    my ($self, %args) = @_;
+    for my $key (qw(label path packages executable desktop)) {
+        exists $args{$key} or die "missing Debian artifact parameter $key\n";
+    }
+    ExternalSoftware::Servicing::Atomic->assert_absolute_path("$args{label} package", $args{path});
