package ExternalSoftware::Servicing::HTTP;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;

use ExternalSoftware::Servicing::Atomic;

sub _host {
    my ($self, $url) = @_;
    $url =~ m{\Ahttps://([^/?#:]+)(?::443)?(?:/|\z)}
        or die "URL is not an approved HTTPS URL\n";
    my $host = lc $1;
    $host =~ /\A(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\z/
        or die "URL contains an invalid host\n";
    return $host;
}

sub _allow {
    my ($self, $url, $allowed_hosts) = @_;
    my %allowed = map { $_ => 1 } @{$allowed_hosts};
    $allowed{$self->_host($url)} or die "URL resolved to an unapproved host\n";
}

sub download {
    my ($self, %args) = @_;
    for my $key (qw(label url destination minimum maximum allowed_hosts content_policy)) {
        exists $args{$key} or die "missing HTTP download parameter $key\n";
    }
    $args{minimum} =~ /\A[0-9]+\z/ && $args{maximum} =~ /\A[0-9]+\z/
        && $args{minimum} <= $args{maximum}
        or die "invalid HTTP download size bounds\n";
    $args{content_policy} =~ /\A(?:artifact|metadata)\z/
        or die "unsupported HTTP content policy\n";
    ExternalSoftware::Servicing::Atomic->assert_absolute_path('download destination', $args{destination});
    $self->_allow($args{url}, $args{allowed_hosts});

    my $partial = "$args{destination}.part";
    unlink $partial if -e $partial || -l $partial;
    my @command = (
        '/usr/bin/curl', '--fail', '--silent', '--show-error', '--location',
        '--proto', '=https', '--proto-redir', '=https', '--connect-timeout', '15',
        '--max-time', '300', '--max-redirs', '8', '--retry', '3', '--retry-delay', '2',
        '--retry-all-errors', '--max-filesize', $args{maximum},
        '--user-agent', 'debian-installer-managed-software/2.0',
        '--header', 'Accept: application/octet-stream, application/vnd.debian.binary-package;q=0.9, */*;q=0.1',
        '--output', $partial, '--write-out', "%{http_code}\n%{url_effective}\n%{content_type}",
        '--url', $args{url},
    );
    open my $curl, '-|', @command or die "failed to execute curl\n";
    my $metadata = do { local $/; <$curl> // q{} };
    close $curl or die "$args{label} download failed\n";
    my ($status, $effective, $content_type) = split /\n/, $metadata, 3;
    defined $status && $status =~ /\A(?:200|206)\z/ or die "$args{label} download returned an unexpected HTTP status\n";
    defined $effective && length($effective) <= 2048 or die "$args{label} effective URL is invalid\n";
    $self->_allow($effective, $args{allowed_hosts});
    $content_type //= q{};
    $content_type = lc((split /;/, $content_type, 2)[0]);
    if ($args{content_policy} eq 'artifact') {
        $content_type !~ /\A(?:text\/(?:html|plain|xml)|application\/(?:json|xml))\z/
            or die "$args{label} download returned a non-artifact content type\n";
    } elsif ($content_type ne q{} && $content_type !~ /\A(?:application\/(?:octet-stream|vnd\.github\+json|json|yaml|x-yaml)|text\/(?:plain|yaml|x-yaml)|binary\/octet-stream)\z/) {
        die "$args{label} download returned an unsupported metadata content type\n";
    }
    -f $partial && !-l $partial or die "$args{label} download is not a regular file\n";
    my $size = -s $partial;
    defined $size && $size >= $args{minimum} && $size <= $args{maximum}
        or die "$args{label} download size is outside approved bounds\n";
    rename $partial, $args{destination} or die "failed to publish downloaded $args{label}: $!\n";
    return $args{destination};
}

1;

package ExternalSoftware::Servicing::State;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::Types::Mooselike qw(Str);

use Fcntl qw(:DEFAULT :flock F_SETFD FD_CLOEXEC O_CREAT O_NOFOLLOW O_RDWR);
use File::Path qw(remove_tree);
use File::Temp qw(tempdir);
use ExternalSoftware::Servicing::Atomic;

has root => (is => 'ro', isa => Str, default => sub { '/var/lib/managed-external-software' });

sub event_dir { return $_[0]->root() . '/events'; }
sub deb_dir   { return $_[0]->root() . '/debs'; }
sub lock_path { return '/run/lock/managed-external-software-update.lock'; }

sub prepare {
    my ($self) = @_;
    ExternalSoftware::Servicing::Atomic->ensure_root_directory($self->root(), 0755);
    ExternalSoftware::Servicing::Atomic->ensure_root_directory($self->event_dir(), 0755);
    ExternalSoftware::Servicing::Atomic->ensure_root_directory($self->deb_dir(), 0755);
    return 1;
}

sub lock {
    my ($self) = @_;
    my $path = $self->lock_path();
    ExternalSoftware::Servicing::Atomic->assert_absolute_path('managed updater lock', $path);
    sysopen my $fh, $path, O_CREAT | O_NOFOLLOW | O_RDWR, 0600
        or die "failed to open updater lock: $!\n";
    fcntl($fh, F_SETFD, FD_CLOEXEC) or die "failed to protect updater lock: $!\n";
    return undef if !flock($fh, LOCK_EX | LOCK_NB);
    return $fh;
}

sub work_dir {
    my ($self) = @_;
    my $path = tempdir('managed-external-software-update.XXXXXX', DIR => '/tmp', CLEANUP => 0);
    chmod 0700, $path or die "failed to set updater workspace mode: $!\n";
    return $path;
}

sub cleanup_work_dir {
    my ($self, $path) = @_;
    ExternalSoftware::Servicing::Atomic->assert_absolute_path('updater workspace', $path);
    $path =~ m{\A/tmp/managed-external-software-update\.[A-Za-z0-9]+\z}
        or die "refusing to remove an unexpected updater workspace\n";
    remove_tree($path, { safe => 1, error => \my $errors });
    @{$errors} and die "failed to clean updater workspace\n";
    return 1;
}

1;

package ExternalSoftware::Servicing::Atomic;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::Types::Mooselike qw(Str);

use Fcntl qw(:DEFAULT O_CREAT O_EXCL O_NOFOLLOW);
use File::Basename qw(dirname);
use File::Path qw(make_path remove_tree);
use File::Spec;

sub assert_absolute_path {
    my ($class, $label, $path) = @_;
    defined $path && $path =~ m{\A/(?:[A-Za-z0-9._@%:+,-]+/)*[A-Za-z0-9._@%:+,-]+\z}
        or die "$label must be a safe absolute path\n";
    return $path;
}

sub assert_child {
    my ($class, $directory, $name) = @_;
    $class->assert_absolute_path('parent directory', $directory);
    defined $name && $name =~ /\A[A-Za-z0-9._:+~,-]+\z/
        or die "unsafe managed filename\n";
    my $path = File::Spec->catfile($directory, $name);
    index($path, "$directory/") == 0 or die "managed path escaped its parent\n";
    return $path;
}

sub ensure_root_directory {
    my ($class, $path, $mode) = @_;
    $class->assert_absolute_path('managed directory', $path);
    if (!-e $path) {
        make_path($path, { mode => $mode }) or die "failed to create $path\n";
    }
    -d $path && !-l $path or die "managed path is not a directory: $path\n";
    my @st = lstat $path or die "failed to stat $path: $!\n";
    $st[4] == 0 or die "managed path must be root-owned: $path\n";
    chmod $mode, $path or die "failed to set mode on $path: $!\n";
    return $path;
}

sub read_limited {
    my ($class, $path, $limit) = @_;
    $class->assert_absolute_path('input path', $path);
    -f $path && !-l $path or die "expected a regular file: $path\n";
    my $size = -s $path;
    defined $size && $size <= $limit or die "input exceeds size limit: $path\n";
    open my $fh, '<:raw', $path or die "failed to read $path: $!\n";
    local $/;
    my $content = <$fh>;
    close $fh or die "failed to close $path: $!\n";
    return defined $content ? $content : q{};
}

sub write_text {
    my ($class, $path, $text, $mode) = @_;
    $class->assert_absolute_path('output path', $path);
    my $directory = dirname($path);
    $class->ensure_root_directory($directory, 0755);
    -l $path and die "output path must not be a symlink: $path\n";
    my $temporary = "$path.tmp.$$";
    sysopen my $fh, $temporary, O_CREAT | O_EXCL | O_WRONLY | O_NOFOLLOW, $mode
        or die "failed to open temporary output $temporary: $!\n";
    print {$fh} $text or die "failed to write temporary output $temporary: $!\n";
    close $fh or die "failed to close temporary output $temporary: $!\n";
    chmod $mode, $temporary or die "failed to set mode on temporary output $temporary: $!\n";
    rename $temporary, $path or die "failed to publish $path: $!\n";
    return $path;
}

sub remove_tree {
    my ($class, $path) = @_;
    $class->assert_absolute_path('removal path', $path);
    return 1 if !-e $path && !-l $path;
    remove_tree($path, { safe => 1, error => \my $errors });
    @{$errors} and die "failed to remove managed path $path\n";
    return 1;
}

