        $self->http()->download(label => 'Tuta Mail AppImage', url => 'https://app.tuta.com/desktop/tutanota-desktop-linux.AppImage',
            destination => $image, minimum => 1_048_576, maximum => 536_870_912, allowed_hosts => ['app.tuta.com'], content_policy => 'artifact');
