            destination => $signature, minimum => 128, maximum => 16_384, allowed_hosts => ['app.tuta.com'], content_policy => 'artifact');
        system('/usr/bin/openssl', 'dgst', '-sha512', '-verify', $key, '-signature', $signature, $image) == 0
            or die "Tuta signature verification failed\n";
        1;
    } or return (1, $@ =~ /signature/i ? 'signature' : 'download');
    my $hash = Digest::SHA->new(256)->addfile($image)->hexdigest();
    my $hash_path = $self->state()->root() . '/tuta.sha256';
    my $old = -f $hash_path ? eval { ExternalSoftware::Servicing::Atomic->read_limited($hash_path, 128) } : q{};
    chomp $old if defined $old;
