        && system('/usr/bin/find', $staged, '-xdev', '-type', 'd', '-exec', '/bin/chmod', '0755', '{}', '+') == 0
        && system('/usr/bin/find', $staged, '-xdev', '-type', 'f', '-exec', '/bin/chmod', 'a-s,go-w', '{}', '+') == 0
        && system('/bin/chmod', '0755', "$staged/AppRun") == 0 or return (1, 'publish');
    my $backup = '/opt/.tuta-mail.previous';
    remove_tree($backup, { safe => 1 }) if -e $backup;
    rename $install, $backup or return (1, 'publish');
    if (!rename $staged, $install) {
        rename $backup, $install;
        return (1, 'publish');
    }
    ExternalSoftware::Servicing::Atomic->write_text($hash_path, "$hash\n", 0644);
    remove_tree($backup, { safe => 1 });
    $self->event()->emit('updated', 'tuta', $old =~ /\A[0-9a-f]{64}\z/ ? 'sha256:' . substr($old, 0, 12) : 'unknown', 'sha256:' . substr($hash, 0, 12));
    return (0, 'updated');
}

