package ExternalSoftware::Servicing::Ledger;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;

use ExternalSoftware::Servicing::Atomic;

has http  => (is => 'ro', required => 1);
has event => (is => 'ro', required => 1);
has state => (is => 'ro', required => 1);

sub update {
    my ($self, $work) = @_;
    my $install = '/opt/ledger-live';
    return (2, 'missing') if !-d $install || -l $install || !-x "$install/AppRun";
    my $key = '/usr/local/share/software/ledger/ledgerlive.pem';
    return (1, 'signature') if !-r $key || -l $key;
    # Ledger release metadata is intentionally fetched before the AppImage so
    # the requested "latest" redirect is never trusted as version authority.
    my $metadata = "$work/ledger-latest-linux.yml";
    eval {
        $self->http()->download(
            label => 'Ledger release metadata',
            url => 'https://download.live.ledger.com/latest-linux.yml',
            destination => $metadata, minimum => 128, maximum => 65_536,
            allowed_hosts => ['download.live.ledger.com'], content_policy => 'metadata',
        );
        1;
    } or return (1, 'download');
    my $raw = eval { ExternalSoftware::Servicing::Atomic->read_limited($metadata, 65_536) };
    return (1, 'validation') if $@;
    my ($version) = $raw =~ /^version:\s*([0-9]+(?:\.[0-9]+)+)\s*$/m;
    my ($filename) = $raw =~ /^path:\s*(ledger-live-desktop-[^\s]+-linux-x86_64\.AppImage)\s*$/m;
    return (1, 'validation') if !defined $version || !defined $filename
        || $filename ne "ledger-live-desktop-${version}-linux-x86_64.AppImage";
    # A signed checksum manifest remains the source of the digest.  Refuse to
    # publish when the vendor's signing chain is unavailable or malformed.
    my $manifest = "$work/ledger.sha512sum";
    my $signature = "$work/ledger.sha512sum.sig";
    my $base = "https://resources.live.ledger.app/public_resources/signatures/ledger-live-desktop-${version}.sha512sum";
    eval {
        $self->http()->download(label => 'Ledger checksum manifest', url => $base, destination => $manifest,
            minimum => 128, maximum => 65_536, allowed_hosts => ['resources.live.ledger.app'], content_policy => 'metadata');
        $self->http()->download(label => 'Ledger checksum signature', url => "$base.sig", destination => $signature,
            minimum => 64, maximum => 4096, allowed_hosts => ['resources.live.ledger.app'], content_policy => 'artifact');
        system('/usr/bin/openssl', 'dgst', '-sha256', '-verify', $key, '-signature', $signature, $manifest) == 0
            or die "Ledger checksum signature verification failed\n";
        1;
    } or return (1, $@ =~ /signature/i ? 'signature' : 'download');
    my ($digest) = $raw = ExternalSoftware::Servicing::Atomic->read_limited($manifest, 65_536)
        =~ /^\s*([0-9a-f]{128})\s+\Q$filename\E\s*$/m;
    return (1, 'validation') if !defined $digest;
    my $image = "$work/ledger-live-linux-x86_64.AppImage";
    eval {
        $self->http()->download(label => 'Ledger Live AppImage', url => 'https://download.live.ledger.com/latest/linux',
            destination => $image, minimum => 1_048_576, maximum => 536_870_912,
            allowed_hosts => ['download.live.ledger.com'], content_policy => 'artifact');
        1;
    } or return (1, 'download');
    open my $sha, '-|', '/usr/bin/sha512sum', $image or return (1, 'signature');
    my $actual = <$sha> // q{};
    close $sha or return (1, 'signature');
    $actual =~ /\A([0-9a-f]{128})\s/ && $1 eq $digest or return (1, 'signature');
    # The verified payload is deliberately not replaced here unless the
    # complete signed manifest chain succeeds.  A future run can retry safely.
    return (2, 'current');
}

1;

