sub _trim {
    my ($value) = @_;
    $value =~ s/\A\s+//;
    $value =~ s/\s+\z//;
    return $value;
}

sub _parse_value {
    my ($label, $value) = @_;
    $value = _trim($value);
    if ($value =~ /\A"(.*)"\z/s) {
        $value = $1;
