    validate_device_path('zram.device', $device);
    my $device_name = _get($config, 'zram', 'device_name');
    $device_name = _device_name_from_path($device) if !defined $device_name || $device_name eq '';
    $device_name =~ /\Azram[0-9]+\z/ or fatal("zram.device_name must be zramN, got '$device_name'");

    my $sysfs_root = _get($config, 'paths', 'sysfs_root');
    my $debugfs_root = _get($config, 'paths', 'debugfs_root');
    my $procfs_root = _get($config, 'paths', 'procfs_root');
    my $runtime_dir = _get($config, 'paths', 'runtime_dir');
    my $lock_file = _get($config, 'runtime', 'lock_file');
    validate_abs_path('paths.sysfs_root', $sysfs_root);
    validate_abs_path('paths.debugfs_root', $debugfs_root);
    validate_abs_path('paths.procfs_root', $procfs_root);
    _validate_runtime_path('paths.runtime_dir', $runtime_dir);
package Zram::Config;

use strict;
use warnings;

use Exporter qw(import);
use Zram::Config::Parser qw(parse_file);
use Zram::Config::Validator qw(normalize_config);
use Zram::Error qw(fatal);
use Zram::Logger qw(set_active_log_level);

our @EXPORT_OK = qw(load_config validate_config cfg cfg_default config);

my %CONFIG;

sub load_config {
    my ($path) = @_;
    my $parsed = parse_file($path);
    my $normalized = normalize_config($parsed);
    %CONFIG = %{$normalized};
    set_active_log_level($CONFIG{ZRAM_LOG_LEVEL} // $ENV{ZRAM_LOG_LEVEL} // 'error');
    return \%CONFIG;
}

sub config {
    return \%CONFIG;
}

sub cfg {
    my ($key) = @_;
    exists $CONFIG{$key} or fatal("missing required zram config key $key");
    return $CONFIG{$key};
}

sub cfg_default {
    my ($key, $default) = @_;
    return exists $CONFIG{$key} ? $CONFIG{$key} : $default;
}

sub validate_config {
    my (%opts) = @_;
    my $require_sysfs = exists $opts{require_sysfs} ? $opts{require_sysfs} : 1;
    if ($require_sysfs) {
        -d cfg('ZRAM_SYSFS') or fatal('zram sysfs path is unavailable: ' . cfg('ZRAM_SYSFS'));
    }
    if (cfg('ZRAM_WRITEBACK_ENABLED')) {
        cfg('ZRAM_SWAP_DEVICE') ne cfg('ZRAM_BACKING_DEVICE')
            or fatal('zram device and writeback backing device must differ');
    }
}

