sub _deb_update {
    my ($self, $http, $deb, $event, $work, $app) = @_;
    my $path = "$work/$app->{name}.deb";
    eval {
        $http->download(
            label => $app->{label}, url => $app->{url}, destination => $path,
            minimum => 1_048_576, maximum => $app->{maximum}, allowed_hosts => $app->{hosts},
