package Zram::Procfs::Reader;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::Types::MooseLike::Numeric qw(PositiveInt);

use Zram::Types qw(decimal_to_millionths);

has max_file_bytes => (
    is      => 'ro',
    isa     => PositiveInt,
    default => sub { 64 * 1024 },
);

has max_line_bytes => (
    is      => 'ro',
    isa     => PositiveInt,
    default => sub { 4096 },
);

sub _read_lines {
    my ($self, $path) = @_;
    open my $fh, '<', $path or return [];
    my (@lines, $bytes);
    while (my $line = <$fh>) {
        $bytes += length($line);
        $bytes <= $self->max_file_bytes()
            or die "zram procfs input exceeds byte limit: $path\n";
        length($line) <= $self->max_line_bytes()
            or die "zram procfs input line exceeds byte limit: $path\n";
        push @lines, $line;
    }
    close $fh or die "failed to close zram procfs input $path: $!\n";
    return \@lines;
}

sub memory_psi {
    my ($self, $path) = @_;
    my %psi = (some => 0, full => 0);
    for my $line (@{$self->_read_lines($path)}) {
        $line =~ /\A(some|full)\s/ or next;
        my $field = $1;
        $line =~ /(?:\A|\s)avg10=([0-9]+(?:\.[0-9]+)?)(?:\s|\z)/ or next;
        $psi{$field} = decimal_to_millionths("memory PSI $field avg10", $1);
    }
    return \%psi;
}

sub meminfo {
    my ($self, $path) = @_;
    my %mem = (available => 0, total => 0);
    for my $line (@{$self->_read_lines($path)}) {
        if ($line =~ /\AMemAvailable:\s+([0-9]+)\s+kB\b/) {
            $mem{available} = (0 + $1) * 1024;
        } elsif ($line =~ /\AMemTotal:\s+([0-9]+)\s+kB\b/) {
            $mem{total} = (0 + $1) * 1024;
        }
        last if $mem{available} && $mem{total};
    }
    return \%mem;
}

