package Zram::Pressure::Evaluator;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::Types::MooseLike::Numeric qw(PositiveInt);

has max_reason_bytes => (
    is      => 'ro',
    isa     => PositiveInt,
    default => sub { 512 },
);

sub _reason {
    my ($self, $value) = @_;
    $value = substr($value, 0, $self->max_reason_bytes());
    return $value;
}

sub evaluate {
    my ($self, $snapshot, $thresholds) = @_;
    ref $snapshot eq 'HASH' && ref $thresholds eq 'HASH'
        or die "zram pressure evaluator requires hash references\n";
    my $available = 0 + ($snapshot->{mem_available_bytes} // 0);
    my $total = 0 + ($snapshot->{mem_total_bytes} // 0);
    my $some = 0 + ($snapshot->{psi_some_avg10_millionths} // 0);
    my $full = 0 + ($snapshot->{psi_full_avg10_millionths} // 0);
    my $available_pct = $total > 0 ? int(($available * 100 + $total - 1) / $total) : 0;
    my @emergency;
    my @pressure;

    push @emergency, $self->_reason("MemAvailablePct=$available_pct<=$thresholds->{emergency_mem_available_pct}")
        if $total > 0 && $available_pct <= $thresholds->{emergency_mem_available_pct};
    push @emergency, 'PSI some avg10 reached emergency threshold'
        if $some >= $thresholds->{emergency_some};
    push @emergency, 'PSI full avg10 reached emergency threshold'
        if $full >= $thresholds->{emergency_full};
    push @pressure, $self->_reason("MemAvailablePct=$available_pct<=$thresholds->{pressure_mem_available_pct}")
        if $total > 0 && $available_pct <= $thresholds->{pressure_mem_available_pct};
    push @pressure, 'PSI some avg10 reached pressure threshold'
        if $some >= $thresholds->{pressure_some};
    push @pressure, 'PSI full avg10 reached pressure threshold'
        if $full >= $thresholds->{pressure_full};
    push @pressure, 'MemAvailable bytes below configured floor'
        if $thresholds->{minimum_free} > 0 && $available > 0 && $available <= $thresholds->{minimum_free};

    my $facts = {
        mem_available_bytes => $available,
        mem_total_bytes => $total,
        mem_available_percent => $available_pct,
        psi_some_avg10_millionths => $some,
        psi_full_avg10_millionths => $full,
    };
    return ('emergency', \@emergency, $facts) if @emergency;
    return ('pressure', \@pressure, $facts) if @pressure;
    return ('normal', ['below pressure thresholds'], $facts);
}

