    62	    my $timeout_ms = int($timeout_sec * 1000);
    63	    $timeout_ms = 1 if $timeout_ms < 1;
    64	    my $ready = $poll->poll($timeout_ms);
    65	    if (!defined $ready || $ready < 0) {
    66	        return 0 if $! == EINTR;
    67	        fatal("zram PSI poll failed: $!");
    68	    }
    69	    if ($ready > 0) {
    70	        for my $trigger (@triggers) {
    71	            my $events = $poll->events($trigger->{fh});
    72	            next if !defined $events;
    73	            if ($events & (POLLERR | POLLHUP | POLLNVAL)) {
    74	                fatal("zram PSI $trigger->{kind} trigger became unavailable");
    75	            }
    76	        }
    77	    }
    78	    return $ready > 0 ? 1 : 0;
    79	}
