    19	my %STATE_BATCH_KEY = (
    20	    normal    => 'ZRAM_WRITEBACK_BATCH_SIZE_NORMAL',
    21	    pressure  => 'ZRAM_WRITEBACK_BATCH_SIZE_PRESSURE',
    22	    emergency => 'ZRAM_WRITEBACK_BATCH_SIZE_EMERGENCY',
    23	);
    24	
    25	my %STATE_PASS_KEY = (
    26	    pressure  => 'ZRAM_WRITEBACK_MAX_PAGES_PRESSURE',
    27	    emergency => 'ZRAM_WRITEBACK_MAX_PAGES_EMERGENCY',
    28	);
    29	
    30	sub _validate_state {
    31	    my ($state) = @_;
    32	    defined $state && exists $STATE_BATCH_KEY{$state}
    33	        or fatal("invalid zram tuning state: " . (defined $state ? $state : 'unset'));
    34	    return $state;
    35	}
    36	
    37	sub _positive_min {
    38	    my (@values) = @_;
    39	    my $minimum;
    40	    for my $value (@values) {
    41	        next if !defined $value || $value <= 0;
    42	        $minimum = $value if !defined $minimum || $value < $minimum;
    43	    }
    44	    return $minimum;
    45	}
    46	
    47	sub _device_sysfs_name {
    48	    my ($device) = @_;
    49	    return undef if !defined $device || $device eq '';
    50	    my $canonical = canonical_path($device);
    51	    return undef if !defined $canonical || $canonical eq '';
    52	    my $name = basename($canonical);
    53	    return $name =~ /\A[A-Za-z0-9_.:+-]+\z/ ? $name : undef;
    54	}
    55	
    56	sub _backing_queue_values {
    57	    my ($attr) = @_;
    58	    my $sysfs_root = cfg('ZRAM_SYSFS_ROOT');
    59	    $sysfs_root =~ s{/+\z}{};
    60	    my %seen;
    61	    my @values;
    62	    for my $device (cfg('ZRAM_BACKING_RAW_DEVICE'), cfg('ZRAM_BACKING_DEVICE')) {
    63	        my $name = _device_sysfs_name($device);
    64	        next if !defined $name;
    65	        next if $seen{$name}++;
    66	        my $value = read_uint_attr("$sysfs_root/class/block/$name/queue/$attr");
    67	        push @values, $value if defined $value;
    68	    }
    69	    return @values;
    70	}
