   108	sub writeback_pass_pages_for_state {
   109	    my ($state, $budget_pages_available) = @_;
   110	    _validate_state($state);
   111	    return 0 if $state eq 'normal';
   112	    return 0 if defined $budget_pages_available && $budget_pages_available <= 0;
   113	
   114	    my $pass_limit = cfg($STATE_PASS_KEY{$state});
   115	    return _positive_min($pass_limit, $budget_pages_available) // 0;
