   118	sub writeback_tuning_snapshot {
   119	    my ($state, $budget_pages_available) = @_;
   120	    _validate_state($state);
   121	    my $configured_target = cfg('ZRAM_WRITEBACK_BATCH_SIZE_ADAPTIVE')
   122	        ? cfg($STATE_BATCH_KEY{$state})
   123	        : cfg('ZRAM_WRITEBACK_BATCH_SIZE');
   124	    my $queue_depth = backing_queue_depth();
   125	    my $rotational = backing_rotational();
   126	    return {
   127	        state => $state,
   128	        adaptive => cfg('ZRAM_WRITEBACK_BATCH_SIZE_ADAPTIVE') ? 1 : 0,
   129	        configured_max => cfg('ZRAM_WRITEBACK_BATCH_SIZE'),
   130	        configured_target => $configured_target,
   131	        queue_depth => $queue_depth,
   132	        rotational => $rotational,
   133	        effective_batch_size => _writeback_batch_size_for_state(
   134	            $state,
   135	            $queue_depth,
   136	            $rotational,
   137	        ),
   138	        pass_page_limit => writeback_pass_pages_for_state($state, $budget_pages_available),
   139	    };
   140	}
   141	
   142	sub apply_writeback_batch_size {
   143	    my ($state) = @_;
   144	    my $snapshot = writeback_tuning_snapshot($state, undef);
