    14	our @EXPORT_OK = qw(ensure_runtime_dir acquire_lock try_acquire_lock);
    15	
    16	sub ensure_runtime_dir {
    17	    my $dir = cfg('ZRAM_RUNTIME_DIR');
    18	    validate_abs_path('runtime_dir', $dir);
    19	    if (!-d $dir) {
    20	        mkdir $dir, 0750 or fatal("failed to create zram runtime dir $dir: $!");
    21	    }
    22	    my @st = lstat($dir) or fatal("failed to stat zram runtime dir $dir: $!");
    23	    -l _ and fatal("zram runtime dir must not be a symlink: $dir");
    24	    -d _ or fatal("zram runtime path is not a directory: $dir");
    25	    ($st[4] == 0 || (cfg_default('ZRAM_DRY_RUN', 0) && $st[4] == $>))
    26	        or fatal("zram runtime dir must be owned by root: $dir");
    27	    chmod 0750, $dir or fatal("failed to chmod zram runtime dir $dir: $!");
    28	}
    29	
    30	sub _ensure_lock_parent {
    31	    my ($path) = @_;
    32	    my $dir = dirname($path);
    33	    validate_abs_path('lock parent', $dir);
    34	    if (!-d $dir) {
    35	        mkdir $dir, 0750 or fatal("failed to create zram lock parent $dir: $!");
    36	    }
    37	    my @st = lstat($dir) or fatal("failed to stat zram lock parent $dir: $!");
    38	    -l _ and fatal("zram lock parent must not be a symlink: $dir");
    39	    -d _ or fatal("zram lock parent is not a directory: $dir");
    40	    ($st[4] == 0 || (cfg_default('ZRAM_DRY_RUN', 0) && $st[4] == $>))
    41	        or fatal("zram lock parent must be owned by root: $dir");
    42	    chmod 0750, $dir or fatal("failed to chmod zram lock parent $dir: $!");
    43	}
    44	
    45	sub _open_lock_file {
    46	    my $path = cfg('ZRAM_LOCK_FILE');
    47	    validate_abs_path('lock_file', $path);
    48	    ensure_runtime_dir();
    49	    _ensure_lock_parent($path);
    50	    -l $path and fatal("zram lock file must not be a symlink: $path");
    51	    sysopen my $fh, $path, O_CREAT | O_WRONLY | O_APPEND | O_NOFOLLOW, 0600
    52	        or fatal("failed to open zram lock $path: $!");
    53	    chmod 0600, $path or fatal("failed to chmod zram lock $path: $!");
    54	    my $flags = fcntl($fh, F_GETFD, 0);
    55	    fcntl($fh, F_SETFD, $flags | FD_CLOEXEC)
    56	        or fatal("failed to set close-on-exec on zram lock $path: $!");
    57	    return ($fh, $path);
    58	}
    59	
    60	sub try_acquire_lock {
    61	    my ($fh, $path) = _open_lock_file();
    62	    if (!flock($fh, LOCK_EX | LOCK_NB)) {
    63	        log_msg('info', 'another zram-writeback run is active; skipping this pass');
    64	        return undef;
    65	    }
    66	    return $fh;
    67	}
    68	
    69	sub acquire_lock {
    70	    my $fh = try_acquire_lock();
    71	    exit 0 if !defined $fh;
    72	    return $fh;
    73	}
