    13	use Zram::Error qw(fatal);
    14	use Zram::Policy qw(run_maintenance);
    15	
    16	our @EXPORT_OK = qw(dispatch requires_lock requires_sysfs);
    17	
    18	sub _canonical_action {
    19	    my ($action) = @_;
    20	    return 'maintenance' if $action eq 'run';
    21	    return 'maintenance' if $action eq 'idle';
    22	    return 'maintenance' if $action eq 'idle-writeback';
    23	    return 'maintenance' if $action eq 'cold-tier';
    24	    return 'writeback-spec' if $action eq 'writeback';
    25	    return 'metrics' if $action eq 'snapshot';
    26	    return $action;
    27	}
    28	
    29	sub requires_lock {
    30	    my ($action) = @_;
    31	    $action = _canonical_action($action);
    32	    return 0 if $action eq 'status';
    33	    return 0 if $action eq 'validate-runtime';
    34	    return 0 if $action eq 'daemon';
    35	    return 1;
    36	}
    37	
    38	sub requires_sysfs {
    39	    my ($action) = @_;
    40	    $action = _canonical_action($action);
    41	    return 0 if $action eq 'status';
    42	    return 0 if $action eq 'reset-state';
    43	    return 1;
    44	}
    45	
    46	sub dispatch {
    47	    my ($action, @args) = @_;
    48	    my $canonical = _canonical_action($action);
    49	    if ($canonical eq 'maintenance') {
    50	        my %opts;
    51	        if (@args) {
    52	            my $arg = shift @args;
    53	            $arg =~ /\A--state=(normal|pressure|emergency)\z/
    54	                or fatal("usage: zram-writeback $action [--state=normal|pressure|emergency]");
    55	            $opts{state} = $1;
    56	            @args and fatal("usage: zram-writeback $action [--state=normal|pressure|emergency]");
    57	        }
    58	        run_maintenance(%opts);
    59	        return 0;
    60	    }
    61	    if ($canonical eq 'metrics') {
    62	        my $print = $action eq 'metrics' ? 1 : 0;
    63	        return Zram::Command::Metrics::run($action eq 'snapshot' ? 'snapshot' : 'metrics', $print);
    64	    }
    65	    if ($canonical eq 'writeback-spec') {
    66	        return Zram::Command::Writeback::run(@args);
    67	    }
    68	    if ($canonical eq 'status') {
    69	        return Zram::Command::Status::run(@args);
    70	    }
    71	    if ($canonical eq 'validate-runtime') {
    72	        @args and fatal('usage: zram-writeback validate-runtime');
    73	        return 0;
    74	    }
    75	    if ($canonical eq 'apply') {
    76	        return Zram::Command::Apply::run(@args);
    77	    }
    78	    if ($canonical eq 'daemon') {
    79	        @args and fatal('usage: zram-writeback daemon');
    80	        return run_daemon();
    81	    }
    82	    if ($canonical eq 'reset-state') {
    83	        return Zram::Command::Reset::run(@args);
    84	    }
    85	    fatal("unknown zram-writeback command: $action");
    86	}
    87	
    88	1;

