     1	package Zram::Command::Reset;
     2	
     3	use strict;
     4	use warnings;
     5	
     6	use Moo;
     7	use MooX::StrictConstructor;
     8	
     9	use Exporter qw(import);
    10	use Zram::Budget qw(budget_state_file);
    11	use Zram::Config qw(cfg);
    12	use Zram::Error qw(fatal);
    13	use Zram::Logger qw(log_msg);
    14	use Zram::Metrics qw(snapshot_file);
    15	
    16	our @EXPORT_OK = qw(run);
    17	
    18	sub _state_paths {
    19	    my $runtime_dir = cfg('ZRAM_RUNTIME_DIR');
    20	    my %seen;
    21	    my @paths = grep { defined $_ && $_ ne '' && !$seen{$_}++ } (
    22	        snapshot_file(),
    23	        budget_state_file(),
    24	    );
    25	
    26	    return @paths if !-d $runtime_dir;
    27	
    28	    opendir my $dh, $runtime_dir or fatal("failed to read zram runtime dir $runtime_dir: $!");
    29	    while (my $entry = readdir $dh) {
    30	        next if $entry eq '.' || $entry eq '..';
    31	        next if $entry !~ /\.(?:metrics|budget|snapshot|state)\z/;
    32	        my $path = "$runtime_dir/$entry";
    33	        next if $seen{$path}++;
    34	        push @paths, $path;
    35	    }
    36	    closedir $dh or fatal("failed to close zram runtime dir $runtime_dir: $!");
    37	
    38	    return @paths;
    39	}
    40	
    41	sub run {
    42	    return __PACKAGE__->new()->execute(@_);
    43	}
    44	
    45	sub execute {
    46	    my ($self, @args) = @_;
    47	    @args and fatal('usage: zram-writeback reset-state');
    48	
    49	    my $removed = 0;
    50	    for my $path (_state_paths()) {
    51	        next if !-e $path && !-l $path;
    52	        if (-d $path) {
    53	            log_msg('warning', "skipping unexpected directory in zram runtime state cleanup: $path");
    54	            next;
    55	        }
    56	        unlink $path or fatal("failed to remove zram runtime state $path: $!");
    57	        $removed++;
    58	    }
    59	
    60	    log_msg('info', "removed $removed zram runtime state file(s)");
    61	    return 0;
    62	}
    63	
    64	1;

