   445	sub block_state_authoritative {
   446	    my ($stats) = @_;
   447	    return ($stats->{block_state_available} && !$stats->{block_state_truncated}) ? 1 : 0;
   448	}
   449	
   450	sub candidate_count {
   451	    my ($stats, @keys) = @_;
   452	    my $count = 0;
   453	    for my $key (@keys) {
   454	        my $value = $stats->{$key} || 0;
   455	        $count = $value if $value > $count;
   456	    }
   457	    return $count;
   458	}
   459	
   460	sub has_candidate {
   461	    my ($stats, @keys) = @_;
   462	    return 1 if !block_state_authoritative($stats);
   463	    return candidate_count($stats, @keys) > 0 ? 1 : 0;
   464	}
   465	
   466	sub has_candidate_at_least {
   467	    my ($stats, $minimum, @keys) = @_;
   468	    return 1 if !block_state_authoritative($stats);
   469	    return candidate_count($stats, @keys) >= $minimum ? 1 : 0;
   470	}
   471	
   472	sub has_huge_idle_candidate {
   473	    my ($stats) = @_;
   474	    return 1 if !block_state_authoritative($stats);
   475	    return ($stats->{huge_idle_pages} || 0) > 0 ? 1 : 0;
   476	}
