     1	package Zram::Setup::Mapper;
     2	
     3	use strict;
     4	use warnings;
     5	
     6	use Moo;
     7	use MooX::StrictConstructor;
     8	use MooX::Types::Mooselike qw(Str);
     9	
    10	use IPC::Open3 qw(open3);
    11	use Symbol qw(gensym);
    12	use Time::HiRes qw(sleep);
    13	use Zram::Config qw(cfg);
    14	use Zram::Error qw(fatal);
    15	use Zram::Path qw(same_path);
    16	
    17	has mapper_name => (is => 'ro', isa => Str, default => sub { cfg('ZRAM_BACKING_MAPPER_NAME') });
    18	has mapper_path => (is => 'ro', isa => Str, default => sub { cfg('ZRAM_BACKING_DEVICE') });
    19	has raw_path    => (is => 'ro', isa => Str, default => sub { cfg('ZRAM_BACKING_RAW_DEVICE') });
    20	
    21	sub _capture {
    22	    my ($self, @command) = @_;
    23	    my $stderr = gensym;
    24	    my $pid = open3(undef, my $stdout, $stderr, @command);
    25	    my $out = do { local $/; <$stdout> // '' };
    26	    my $err = do { local $/; <$stderr> // '' };
    27	    waitpid $pid, 0;
    28	    return ($? >> 8, $out, $err);
    29	}
    30	
    31	sub _run {
    32	    my ($self, @command) = @_;
    33	    system @command;
    34	    return $? == 0;
    35	}
    36	
    37	sub _wait_for_mapper {
    38	    my ($self, $seconds) = @_;
    39	    for (1 .. $seconds) {
    40	        return 1 if -b $self->mapper_path();
    41	        sleep 1;
    42	    }
    43	    return -b $self->mapper_path() ? 1 : 0;
    44	}
    45	
    46	sub _mapped_source {
    47	    my ($self) = @_;
    48	    my ($status, $out) = $self->_capture('/usr/sbin/cryptsetup', 'status', $self->mapper_name());
    49	    return undef if $status != 0;
    50	    my ($source) = $out =~ /^\s*device:\s*(\S+)\s*$/m;
    51	    return $source;
    52	}
    53	
    54	sub ensure_open {
    55	    my ($self) = @_;
    56	    -b $self->raw_path() or fatal('missing raw zram writeback partition ' . $self->raw_path());
    57	    if (-b $self->mapper_path()) {
    58	        my $source = $self->_mapped_source();
    59	        defined $source && same_path($source, $self->raw_path())
    60	            or fatal('existing zram writeback mapper does not match its configured raw backing device');
    61	        return 1;
    62	    }
    63	
    64	    for my $module (qw(dm_mod dm_crypt)) {
    65	        $self->_run('/usr/sbin/modprobe', $module);
    66	    }
    67	    my $key_bytes = cfg('DMCRYPT_EPHEMERAL_KEY_SIZE') / 8;
    68	    $self->_run(
    69	        '/usr/sbin/cryptsetup',
    70	        'open',
    71	        '--type', 'plain',
    72	        '--batch-mode',
    73	        '--key-file', cfg('DMCRYPT_RANDOM_KEY_FILE'),
    74	        '--keyfile-size', $key_bytes,
    75	        '--cipher', cfg('DMCRYPT_EPHEMERAL_CIPHER'),
    76	        '--key-size', cfg('DMCRYPT_EPHEMERAL_KEY_SIZE'),
    77	        '--hash', cfg('DMCRYPT_EPHEMERAL_HASH'),
    78	        $self->raw_path(),
    79	        $self->mapper_name(),
    80	    ) or fatal('failed to open ephemeral zram writeback mapper ' . $self->mapper_name());
    81	    $self->_wait_for_mapper(10)
    82	        or fatal('zram writeback mapper did not appear: ' . $self->mapper_path());
    83	    return 1;
    84	}
    85	
    86	sub close {
    87	    my ($self) = @_;
    88	    return 1 if !-b $self->mapper_path();
    89	    my $source = $self->_mapped_source();
    90	    defined $source && same_path($source, $self->raw_path())
    91	        or fatal('zram writeback mapper does not match its configured raw backing device');
    92	    $self->_run('/usr/sbin/cryptsetup', 'close', $self->mapper_name())
    93	        or fatal('failed to close ephemeral zram writeback mapper ' . $self->mapper_name());
    94	    return 1;
    95	}
