    24	sub snapshot_file {
    25	    my $configured = cfg_default('ZRAM_METRICS_FILE', '');
    26	    return $configured if defined $configured && $configured ne '';
    27	    my $dev = cfg('ZRAM_SWAP_DEVICE');
