    32	sub block_state_line_limit {
    33	    my ($disksize, $logical_block_size, %limits) = @_;
    34	    my $maximum = $limits{maximum};
    35	    my $fallback = $limits{fallback};
    36	    my $logical_block_size_fallback = $limits{logical_block_size_fallback};
    37	    defined $maximum && $maximum > 0 or fatal('block-state maximum line limit must be positive');
    38	    defined $fallback && $fallback > 0 or fatal('block-state fallback line limit must be positive');
    39	    $fallback <= $maximum or fatal('block-state fallback line limit must not exceed the maximum');
    40	    defined $logical_block_size_fallback && $logical_block_size_fallback > 0
    41	        or fatal('logical block size fallback must be positive');
    42	    return $fallback if !defined $disksize || $disksize <= 0;
    43	    $logical_block_size = $logical_block_size_fallback
    44	        if !defined $logical_block_size || $logical_block_size <= 0;
    45	    my $device_pages = int(($disksize + $logical_block_size - 1) / $logical_block_size);
    46	    my $limit = $device_pages + 1;
    47	    return $limit < $maximum ? $limit : $maximum;
    48	}
