sub expect_rejection {
    my ($code, $label) = @_;
    my $pid = fork();
    defined $pid or die "fork $label";
    if (!$pid) {
        local $ENV{PATH} = q{};
        $code->();
        exit 0;
    }
    waitpid $pid, 0;
    die "$label was accepted" if $? == 0;
}

my ($mem_fh, $mem_path) = tempfile();
