my ($psi_fh, $psi_path) = tempfile();
print {$psi_fh} "some avg10=0.50 avg60=0.00 avg300=0.00 total=1\nfull avg10=0.30 avg60=0.00 avg300=0.00 total=1\n" or die "write psi";
close $psi_fh or die "close psi";
my $reader = Zram::Procfs::Reader->new();
