die "meminfo parse" if $mem->{total} != 8_388_608 || $mem->{available} != 2_097_152;
my $psi = $reader->memory_psi($psi_path);
die "psi parse" if $psi->{some} != 500_000 || $psi->{full} != 300_000;

my $evaluator = Zram::Pressure::Evaluator->new();
my ($state, $reasons, $facts) = $evaluator->evaluate(
