    pressure_cooldown_seconds => 120,
    emergency_cooldown_seconds => 30,
    recovery_hysteresis_seconds => 180,
);
my $first = $controller->observe(0, "pressure");
die "first pressure decision" if !$first->{run} || $first->{tune} ne "pressure";
$controller->tuning_applied("pressure");
$controller->pass_completed("pressure", 0);
my $suppressed = $controller->observe(30, "pressure");
die "cooldown decision" if $suppressed->{run};
my $escalated = $controller->observe(31, "emergency");
die "escalation decision" if !$escalated->{run} || $escalated->{tune} ne "emergency";
$controller->tuning_applied("emergency");
$controller->pass_completed("emergency", 31);
my $recovering = $controller->observe(40, "normal");
die "premature recovery" if $recovering->{recovered};
my $recovered = $controller->observe(220, "normal");
die "recovery decision" if !$recovered->{recovered} || $recovered->{tune} ne "normal";
my $no_cooldown = Zram::Daemon::Controller->new(
    pressure_cooldown_seconds => 0,
    emergency_cooldown_seconds => 0,
    recovery_hysteresis_seconds => 0,
);
