    76	sub reset {
    77	    my ($self) = @_;
    78	    my $device = cfg('ZRAM_SWAP_DEVICE');
    79	    -d cfg('ZRAM_SYSFS') or fatal('zram sysfs path is unavailable: ' . cfg('ZRAM_SYSFS'));
